B.l3=new A.a4(B.oM,["\ub2e8\ub3c5 \uacb0\uc815 \uc804 \ud544\uc218 \uc870\uac74 \ud655\uc778","\uacf5\ub3d9 \uc9c0\ucd9c\uacfc \uac1c\uc778 \uc9c0\ucd9c \ubd84\ub9ac","\ubc18\ubcf5 \uc81c\uacf5 \uac00\ub2a5\ud55c \uacb0\uacfc\ubb3c\uacfc \uc18c\uc694 \uc2dc\uac04 \uae30\ub85d","\uc0c8 \uc544\uc774\ub514\uc5b4\ubcf4\ub2e4 \uc9c4\ud589 \uc911\uc778 \uc77c \ub9c8\uac10 \uc6b0\uc120","\uc2dc\uac04/\ube44\uc6a9/\ucc45\uc784 \ud655\uc778 \ud6c4 \uc751\ub2f5","\uc57d\uc18d\ud55c \ube44\uc6a9\uacfc \uc77c\uc815 \ubaa9\ub85d\ud654","\uae34\uae09 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc870\uac74 \ud655\uc778 \uc720\uc9c0","\ubd80\ud0c1 \uc218\ub77d \uc804 \uac10\ub2f9 \ubc94\uc704 \uc124\uc815","\uac00\ub2a5\uc131\ubcf4\ub2e4 \uc2e4\uc81c \ud544\uc694 \uc790\uc6d0 \ud655\uc778","\uc900\ube44\ud55c \ub0b4\uc6a9\uc744 \uc791\uc740 \uacb0\uacfc\ubb3c\ub85c \uc804\ud658"],t.w)
B.RE=new A.ic("\ub0b4 \uae30\uc900 / \ub3d9\ub8cc","\uc77c\uac04\uacfc \uac19\uc740 \uc624\ud589/\uac19\uc740 \uc74c\uc591\uc785\ub2c8\ub2e4. \uc804\ud1b5\uc801\uc73c\ub85c \uc790\uc2e0\uacfc \ub098\ub780\ud788 \uc11c\ub294 \ud798, \ub3c5\ub9bd\uc131, \ub3d9\ub8cc \uad00\uacc4\ub97c \uc0c1\uc9d5\ud569\ub2c8\ub2e4.","\ub0b4 \ubc29\uc2dd\ub9cc \uc815\ub2f5\uc774\ub77c\uace0 \ubc00\uc5b4\ubd99\uc774\uac70\ub098 \uac00\uae4c\uc6b4 \uc0ac\ub78c\uacfc \uc0ac\uc18c\ud55c \ube44\uad50\ub97c \uacc4\uc18d\ud558\ub294 \ud589\ub3d9\uc744 \uc870\uc2ec\ud574\ubcf4\uc138\uc694.","\uc624\ub298 \ud560 \uc77c \ud558\ub098\ub97c \ub0b4 \uae30\uc900\uc73c\ub85c \uc815\ud55c \ub4a4, \ud568\uaed8\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc6d0\ud558\ub294 \ubc29\uc2dd\uc744 \uba3c\uc800 \ubb3c\uc5b4\ubcf4\uc138\uc694.","\u201c\ub098\ub294 \uc774\ub807\uac8c \uc0dd\uac01\ud574. \ub108\ub294 \uc5b4\ub5a4 \ubc29\uc2dd\uc774 \ud3b8\ud574?\u201d\ub77c\uace0 \uc120\ud0dd\uc758 \uc5ec\uc9c0\ub97c \ub0a8\uaca8\ubcf4\uc138\uc694.","\uc9c0\uae08 \uc9c0\ud0a4\ub824\ub294 \uac83\uc740 \ub0b4 \uac00\uce58\uc77c\uae4c\uc694, \ub2e8\uc9c0 \uc775\uc219\ud55c \ubc29\uc2dd\uc77c\uae4c\uc694?")
B.RJ=new A.ic("\ud611\ub825 / \uacbd\uacc4","\uc77c\uac04\uacfc \uac19\uc740 \uc624\ud589/\ub2e4\ub978 \uc74c\uc591\uc785\ub2c8\ub2e4. \ub3d9\ub8cc\uc640\uc758 \ud611\ub825, \uacbd\uc7c1, \uc790\uc6d0\uc744 \ub098\ub204\ub294 \ubb38\uc81c\ub97c \uc0c1\uc9d5\ud569\ub2c8\ub2e4. \uc774\ub984\uc774 \uace7 \uc7ac\uc0b0 \uc190\uc2e4\uc744 \ub73b\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.","\ubd84\uc704\uae30\uc5d0 \ud729\uc4f8\ub824 \uc6d0\uce58 \uc54a\ub294 \uc57d\uc18d\uc744 \ud558\uac70\ub098, \ud568\uaed8 \uc4f0\ub294 \uc2dc\uac04\uacfc \ube44\uc6a9\uc744 \ub9d0\uc5c6\uc774 \ub5a0\ub9e1\uc9c0 \uc54a\ub3c4\ub85d \ud574\ubcf4\uc138\uc694.","\ubaa8\uc784\uc774\ub098 \ud611\uc5c5\uc744 \uc815\ud560 \ub54c \u201c\ub204\uac00 \ubb34\uc5c7\uc744 \uc5b8\uc81c\uae4c\uc9c0\u201d \ud560\uc9c0 \uc9e7\uac8c \uc815\ub9ac\ud558\uc138\uc694.","\u201c\uc5ec\uae30\uae4c\uc9c0\ub294 \ub3c4\uc6b8 \uc218 \uc788\uc5b4. \uadf8\ub2e4\uc74c\uc740 \ud568\uaed8 \ub098\ub204\uba74 \uc88b\uaca0\uc5b4.\u201d\ub77c\uace0 \uacbd\uacc4\ub97c \uc54c\ub824\uc8fc\uc138\uc694.","\uc88b\uc740 \uad00\uacc4\ub97c \uc9c0\ud0a4\ub824\uace0 \ubb34\ub9ac\ud558\uac8c \uc57d\uc18d\ud55c \uac83\uc740 \uc5c6\ub098\uc694?")
B.RG=new A.ic("\uafb8\uc900\ud55c \ud45c\ud604 / \uc0dd\ud65c","\uc77c\uac04\uc774 \uc0dd\ud558\ub294 \uc624\ud589/\uac19\uc740 \uc74c\uc591\uc785\ub2c8\ub2e4. \uc0dd\uc0b0, \uae30\uc220, \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ud45c\ud604\uacfc \uc77c\uc0c1\uc758 \uc990\uac70\uc6c0\uc744 \uc0c1\uc9d5\ud569\ub2c8\ub2e4.","\ud3b8\uc548\ud568\uc5d0 \uba38\ubb3c\ub7ec \ub9c8\uac10\uc744 \ubbf8\ub8e8\uac70\ub098 \ud55c \ubc88\uc5d0 \ub108\ubb34 \ub9ce\uc740 \uc77c\uc744 \ubc8c\uc774\uc9c0 \uc54a\ub3c4\ub85d \ud574\ubcf4\uc138\uc694.","20\ubd84 \ub3d9\uc548 \uc791\uc740 \ucd08\uc548 \ud558\ub098\ub97c \uc644\uc131\ud558\uace0, \ub05d\ub0b8 \ub4a4 \uc26c\ub294 \uc2dc\uac04\uc744 \uc815\ud574\ubcf4\uc138\uc694.","\ud3c9\uac00\ubd80\ud130 \ud558\uae30\ubcf4\ub2e4 \u201c\uc5b4\ub5a4 \uacfc\uc815\uc73c\ub85c \ub9cc\ub4e4\uc5c8\uc5b4?\u201d\ub77c\uace0 \ubb3c\uc73c\uba70 \uc774\uc57c\uae30\ub97c \ub4e4\uc5b4\ubcf4\uc138\uc694.","\uc624\ub298 \uc791\uc9c0\ub9cc \ub208\uc5d0 \ubcf4\uc774\uac8c \uc644\uc131\ud560 \uc218 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc778\uac00\uc694?")
B.RI=new A.ic("\uc544\uc774\ub514\uc5b4 / \ub9d0\uc758 \ud798","\uc77c\uac04\uc774 \uc0dd\ud558\ub294 \uc624\ud589/\ub2e4\ub978 \uc74c\uc591\uc785\ub2c8\ub2e4. \ud45c\ud604, \ubcc0\ud654, \uae30\uc874 \ubc29\uc2dd\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc744 \uc0c1\uc9d5\ud569\ub2c8\ub2e4. \ub9d0\ub2e4\ud23c\uc774 \ubc18\ub4dc\uc2dc \uc0dd\uae34\ub2e4\ub294 \ub73b\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\ub9de\ub294 \ub9d0\uc774\uc5b4\ub3c4 \uc0c1\ub300\ub97c \ubab0\uc544\ubd99\uc774\ub294 \ud45c\ud604, \uac10\uc815\uc774 \uc62c\ub77c\uc628 \uc0c1\ud0dc\uc5d0\uc11c \ubc14\ub85c \ubcf4\ub0b4\ub294 \uba54\uc2dc\uc9c0\ub97c \uc870\uc2ec\ud574\ubcf4\uc138\uc694.","\uc911\uc694\ud55c \uba54\uc2dc\uc9c0\ub294 \ubcf4\ub0b4\uae30 \uc804\uc5d0 \ud55c \ubc88 \uc77d\uace0, \uc9c0\uc801 \ud55c \uac00\uc9c0 \uc606\uc5d0 \uc2e4\ud589 \uac00\ub2a5\ud55c \ub300\uc548 \ud55c \uac00\uc9c0\ub97c \uc368\ubcf4\uc138\uc694.","\u201c\uc65c \uc774\ub807\uac8c \ud588\uc5b4?\u201d \ub300\uc2e0 \u201c\uc774\ub807\uac8c \ubc14\uafd4\ubcf4\uba74 \uc5b4\ub5a8\uae4c?\u201d\ub85c \uc2dc\uc791\ud574\ubcf4\uc138\uc694.","\uc9c0\uae08 \ud558\uace0 \uc2f6\uc740 \ub9d0\uc740 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824\ub294 \ub9d0\uc778\uac00\uc694, \ub9c8\uc74c\uc744 \uc3df\uc544\ub0b4\ub824\ub294 \ub9d0\uc778\uac00\uc694?")
B.RD=new A.ic("\uae30\ud68c \ud0d0\uc0c9 / \uad50\ub958","\uc77c\uac04\uc774 \uadf9\ud558\ub294 \uc624\ud589/\uac19\uc740 \uc74c\uc591\uc785\ub2c8\ub2e4. \uc678\ubd80 \uc790\uc6d0, \uad50\ub958, \ub2e4\uc591\ud55c \uae30\ud68c\ub97c \ub2e4\ub8e8\ub294 \uc0c1\uc9d5\uc785\ub2c8\ub2e4. \ub73b\ubc16\uc758 \ub3c8\uc774\ub098 \ud22c\uc790 \uc218\uc775\uc744 \uc608\uace0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uc88b\uc544 \ubcf4\uc774\ub294 \uc81c\uc548\uc5d0 \uc989\ub2f5\ud558\uac70\ub098 \uc0c1\ub300\uc758 \uc124\uba85\ub9cc \ub4e3\uace0 \uc77c\uc815/\ube44\uc6a9/\uc5ed\ud560\uc744 \uc0dd\ub7b5\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud574\ubcf4\uc138\uc694.","\uc0c8 \uc81c\uc548 \ud558\ub098\ub97c \ub9cc\ub098\uba74 \uc7a5\uc810, \ud544\uc694\ud55c \uc2dc\uac04, \ud655\uc778\ud560 \uc870\uac74\uc744 \uac01\uac01 \ud55c \uc904\uc529 \uc801\uc5b4\ubcf4\uc138\uc694.","\u201c\ud765\ubbf8\ub85c\uc6cc. \uad6c\uccb4\uc801\uc778 \uc870\uac74\uc744 \ud655\uc778\ud55c \ub4a4 \ub2f5\ud574\ub3c4 \ub420\uae4c?\u201d\ub77c\uace0 \uc2dc\uac04\uc744 \ud655\ubcf4\ud558\uc138\uc694.","\uc9c0\uae08 \ub04c\ub9ac\ub294 \uac83\uc740 \uc2e4\uc81c \ud544\uc694\uc778\uac00\uc694, \ub193\uce58\uae30 \uc2eb\ub2e4\ub294 \ub9c8\uc74c\uc778\uac00\uc694?")
B.RL=new A.ic("\uad00\ub9ac / \uafb8\uc900\ud55c \ucc45\uc784","\uc77c\uac04\uc774 \uadf9\ud558\ub294 \uc624\ud589/\ub2e4\ub978 \uc74c\uc591\uc785\ub2c8\ub2e4. \uad00\ub9ac \uac00\ub2a5\ud55c \uc790\uc6d0, \uacc4\ud68d, \uc77c\uc0c1\uc801\uc778 \ucc45\uc784\uc744 \uc0c1\uc9d5\ud569\ub2c8\ub2e4. \uc218\uc785\uc758 \ud06c\uae30\ub97c \ud655\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uc791\uc740 \uc190\ud574\uae4c\uc9c0 \ubaa8\ub450 \ud53c\ud558\ub824\ub2e4 \ub354 \ub9ce\uc740 \uc2dc\uac04\uacfc \ub9c8\uc74c\uc744 \uc4f0\uac70\ub098, \uc0c1\ub300\uc5d0\uac8c \ub0b4 \uae30\uc900\uc744 \ub611\uac19\uc774 \uc694\uad6c\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud574\ubcf4\uc138\uc694.","\ub193\uce5c \uc77c\uc815\uc774\ub098 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubb3c\uac74 \ud55c \uac00\uc9c0\ub97c \uc815\ub9ac\ud558\uace0, \uc624\ub298 \ud544\uc694\ud55c \uc77c \uc138 \uac00\uc9c0\ub9cc \ub0a8\uaca8\ubcf4\uc138\uc694.","\u201c\uc6b0\ub9ac \uc11c\ub85c \uae30\ub300\ud558\ub294 \ubc94\uc704\ub97c \uba3c\uc800 \uc815\ud574\ubcfc\uae4c?\u201d\ub77c\uace0 \uad6c\uccb4\uc801\uc73c\ub85c \uc774\uc57c\uae30\ud574\ubcf4\uc138\uc694.","\uc9c0\uae08 \uad00\ub9ac\ud560 \uc218 \uc788\ub294 \uac83\uacfc \ub0b4 \ud798 \ubc16\uc5d0 \uc788\ub294 \uac83\uc744 \ub098\ub220\ubd24\ub098\uc694?")
B.RH=new A.ic("\uacb0\ub2e8 / \ubd80\ub2f4 \uc870\uc808","\uc77c\uac04\uc744 \uadf9\ud558\ub294 \uc624\ud589/\uac19\uc740 \uc74c\uc591\uc785\ub2c8\ub2e4. \uae34\uc7a5, \uaddc\uc728, \uacfc\uc81c\ub97c \ub9c8\uc8fc\ud558\ub294 \ud798\uc744 \uc0c1\uc9d5\ud558\uba70 \uce60\uc0b4\uc774\ub77c\uace0\ub3c4 \ubd80\ub985\ub2c8\ub2e4. \uc0ac\uace0\ub098 \ubd88\ud589\uc758 \uc608\uace0\uac00 \uc544\ub2d9\ub2c8\ub2e4.","\uae09\ud55c \ub9c8\uc74c\uc5d0 \ud655\uc778 \ub2e8\uacc4\ub97c \uc0dd\ub7b5\ud558\uac70\ub098 \ubaa8\ub4e0 \ucc45\uc784\uc744 \ud63c\uc790 \uac10\ub2f9\ud558\ub824\ub294 \ud589\ub3d9\uc744 \uc870\uc2ec\ud574\ubcf4\uc138\uc694.","\uac00\uc7a5 \ubd80\ub2f4\ub418\ub294 \uc77c\uc744 \uc138 \ub2e8\uacc4\ub85c \ub098\ub204\uace0, \uccab \ub2e8\uacc4\uc5d0 \ud544\uc694\ud55c \ub3c4\uc6c0\uc744 \ud55c \uc0ac\ub78c\uc5d0\uac8c \uc694\uccad\ud574\ubcf4\uc138\uc694.","\u201c\uc9c0\uae08\uc740 \uc774 \ubd80\ubd84\uc774 \ubd80\ub2f4\ub3fc. \uc6b0\uc120\uc21c\uc704\ub97c \ud568\uaed8 \uc815\ud574\uc904\ub798?\u201d\ub77c\uace0 \uad6c\uccb4\uc801\uc73c\ub85c \ub9d0\ud574\ubcf4\uc138\uc694.","\ube68\ub9ac \ub05d\ub0b4\ub824\ub294 \ub9c8\uc74c \ub54c\ubb38\uc5d0 \uc0dd\ub7b5\ud55c \ud655\uc778\uc740 \uc5c6\ub098\uc694?")
B.RF=new A.ic("\uc57d\uc18d / \uc2e0\ub8b0","\uc77c\uac04\uc744 \uadf9\ud558\ub294 \uc624\ud589/\ub2e4\ub978 \uc74c\uc591\uc785\ub2c8\ub2e4. \uaddc\uce59, \uc5ed\ud560, \ucc45\uc784\uacfc \uc2e0\ub8b0\ub97c \uc0c1\uc9d5\ud569\ub2c8\ub2e4. \uc2b9\uc9c4\uc774\ub098 \ud569\uaca9\uc744 \ubcf4\uc7a5\ud558\ub294 \ud45c\uc2dc\uac00 \uc544\ub2d9\ub2c8\ub2e4.","\uc2e4\uc218\ud558\uc9c0 \uc54a\uc73c\ub824\ub294 \ub9c8\uc74c\uc5d0 \uc2dc\uc791\uc744 \ubbf8\ub8e8\uac70\ub098 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uae30\ub300\ub97c \ubaa8\ub450 \ucda9\uc871\ud558\ub824 \ud558\uc9c0 \uc54a\ub3c4\ub85d \ud574\ubcf4\uc138\uc694.","\uc624\ub298\uc758 \uc57d\uc18d \ud55c \uac00\uc9c0\ub97c \ud655\uc778\ud558\uace0, \uc5b4\ub824\uc6b4 \uc77c\uc815\uc740 \ub2a6\uae30 \uc804\uc5d0 \uc870\uc815 \uba54\uc2dc\uc9c0\ub97c \ubcf4\ub0b4\ubcf4\uc138\uc694.","\u201c\uc5b8\uc81c\uae4c\uc9c0 \uc5b4\ub290 \uc815\ub3c4\uac00 \ud544\uc694\ud574?\u201d\ub77c\uace0 \uae30\ub300 \uc218\uc900\uc744 \uba3c\uc800 \ub9de\ucdb0\ubcf4\uc138\uc694.","\ucc45\uc784\uac10\uacfc \uacfc\ub3c4\ud55c \ubd80\ub2f4\uc758 \uacbd\uacc4\ub97c \uc5b4\ub514\uc5d0 \ub450\uace0 \uc788\ub098\uc694?")
B.RM=new A.ic("\ud0d0\uad6c / \ub2e4\ub978 \uad00\uc810","\uc77c\uac04\uc744 \uc0dd\ud558\ub294 \uc624\ud589/\uac19\uc740 \uc74c\uc591\uc785\ub2c8\ub2e4. \ub3c5\ud2b9\ud55c \uc774\ud574 \ubc29\uc2dd, \ud0d0\uad6c, \uc9c1\uad00\uc801\uc778 \uc5f0\uacb0\uc744 \uc0c1\uc9d5\ud569\ub2c8\ub2e4.","\uc0c1\ub300\uc758 \ub9d0\ub73b\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \ucd94\uce21\ud558\uac70\ub098 \uc790\ub8cc\ub9cc \ubaa8\uc73c\ub2e4\uac00 \ud589\ub3d9\uc744 \ubbf8\ub8e8\ub294 \uc2b5\uad00\uc744 \uc870\uc2ec\ud574\ubcf4\uc138\uc694.","\uace0\ubbfc\uc744 \u201c\ud655\uc778\ub41c \uc0ac\uc2e4\u201d\uacfc \u201c\ub0b4 \ucd94\uce21\u201d \ub450 \uce78\uc73c\ub85c \ub098\ub204\uace0, \ud655\uc778\ud560 \uc9c8\ubb38 \ud558\ub098\ub97c \uc815\ud574\ubcf4\uc138\uc694.","\u201c\ub0b4\uac00 \uc774\ub807\uac8c \uc774\ud574\ud588\ub294\ub370 \ub9de\uc544?\u201d\ub77c\uace0 \uc9d0\uc791\uc744 \ud655\uc778\ud558\ub294 \uc9c8\ubb38\uc744 \uac74\ub124\ubcf4\uc138\uc694.","\ucda9\ubd84\ud788 \uc0dd\uac01\ud55c \uac83\uacfc \uc544\uc9c1 \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uac83\uc744 \uad6c\ubcc4\ud588\ub098\uc694?")
B.RK=new A.ic("\ubc30\uc6c0 / \ub3cc\ubd04","\uc77c\uac04\uc744 \uc0dd\ud558\ub294 \uc624\ud589/\ub2e4\ub978 \uc74c\uc591\uc785\ub2c8\ub2e4. \ubc30\uc6c0, \ubcf4\ud638, \ubc1b\uc544\ub4e4\uc774\ub294 \ud798\uc744 \uc0c1\uc9d5\ud569\ub2c8\ub2e4.","\ub3c4\uc6c0\uc744 \ubc1b\ub294 \ub370\ub9cc \uc775\uc219\ud574\uc9c0\uac70\ub098 \uc644\ubcbd\ud788 \uc900\ube44\ub420 \ub54c\uae4c\uc9c0 \ud589\ub3d9\uc744 \ubbf8\ub8e8\uc9c0 \uc54a\ub3c4\ub85d \ud574\ubcf4\uc138\uc694.","\ubc30\uc6b4 \uac83 \ud558\ub098\ub97c \ub0b4 \ub9d0\ub85c \uc138 \uc904 \uc694\uc57d\ud558\uace0, \uc624\ub298 \ubc14\ub85c \uc368\ubcfc \uc791\uc740 \ud589\ub3d9\uc744 \ud558\ub098 \uc815\ud574\ubcf4\uc138\uc694.","\uc870\uc5b8\ud558\uae30 \uc804\uc5d0 \u201c\ub4e4\uc5b4\uc8fc\uba74 \uc88b\uc744\uae4c, \uac19\uc774 \ubc29\ubc95\uc744 \ucc3e\uc544\ubcfc\uae4c?\u201d\ub77c\uace0 \ubb3c\uc5b4\ubcf4\uc138\uc694.","\uc9c0\uae08 \ud544\uc694\ud55c \uac83\uc740 \ub354 \ub9ce\uc740 \uc900\ube44\uc778\uac00\uc694, \uc791\uc740 \uc2dc\ub3c4\uc778\uac00\uc694?")
B.dn=new A.a4(B.oM,[B.RE,B.RJ,B.RG,B.RI,B.RD,B.RL,B.RH,B.RF,B.RM,B.RK],A.aq("a4<m,ic>"))
B.a9a=new A.dO("\uc790\uc728\uc131","\uc804\ubb38 \uc2e4\ubb34 / \ub3c5\ub9bd \ud504\ub85c\uc81d\ud2b8","\ub2f4\ub2f9 \ubc94\uc704\uc640 \uacb0\uacfc\ubb3c \uba85\uc2dc")
B.a9g=new A.dO("\ud611\uc5c5","\uc6b4\uc601 \uc870\uc728 / \ud30c\ud2b8\ub108 \ud611\uc5c5","\uc5ed\ud560/\ube44\uc6a9/\uc131\uacfc \ubc30\ubd84 \uc0ac\uc804 \ud569\uc758")
B.a9h=new A.dO("\uafb8\uc900\ud55c \uc81c\uc791","\uc81c\uc791 / \uad50\uc721 \ucf58\ud150\uce20","\uc791\uc740 \uacb0\uacfc\ubb3c \uc644\uc131\uacfc \uc791\uc5c5 \uae30\ub85d")
B.a9c=new A.dO("\ud45c\ud604\uacfc \uac1c\uc120","\uae30\ud68d / \ub514\uc790\uc778 / \ud3b8\uc9d1","\ubb38\uc81c \uc9c0\uc801\uacfc \uc2e4\ud589 \ub300\uc548 \ud568\uaed8 \uc81c\uc2dc")
B.a98=new A.dO("\uc678\ubd80 \uad50\ub958","\uace0\uac1d \uc18c\ud1b5 / \ud504\ub85c\uc81d\ud2b8 \uc6b4\uc601","\ubc94\uc704/\uc77c\uc815/\uc870\uac74 \uc6b0\uc120 \ud655\uc778")
B.a9d=new A.dO("\uad00\ub9ac\uc640 \uc9c0\uc18d","\ud68c\uacc4 \uc9c0\uc6d0 / \uc77c\uc815/\uc790\uc6d0 \uad00\ub9ac","\ubc18\ubcf5 \uc5c5\ubb34 \uc815\ub9ac\uc640 \uc815\ud655\ub3c4 \ud655\uc778")
B.a9b=new A.dO("\uacfc\uc81c \ub300\uc751","\ud604\uc7a5 \uc6b4\uc601 / \ubb38\uc81c \ud574\uacb0","\ud655\uc778 \uc808\ucc28\uc640 \ub3c4\uc6c0 \uc694\uccad \uae30\uc900 \uc124\uc815")
B.a9e=new A.dO("\uaddc\uce59\uacfc \uc2e0\ub8b0","\ud589\uc815 / \ud488\uc9c8/\uc808\ucc28 \uad00\ub9ac","\uc694\uad6c \uc870\uac74\uacfc \uc644\ub8cc \uae30\uc900 \ubb38\uc11c\ud654")
B.a99=new A.dO("\ud0d0\uad6c\uc640 \uc7ac\ud574\uc11d","\uc870\uc0ac / \uc5f0\uad6c \uc9c0\uc6d0 / \ubd84\uc11d","\uc791\uc740 \uc2e4\ud5d8\uc73c\ub85c \uac00\uc124 \ud655\uc778")
B.a9f=new A.dO("\ud559\uc2b5\uacfc \uc804\ub2ec","\uad50\uc721 / \ubb38\uc11c\ud654 / \uc9c0\uc2dd \uad00\ub9ac","\ubc30\uc6b4 \ub0b4\uc6a9\uc758 \uacb0\uacfc\ubb3c\ud654")
